90	    pub limit_name: String,
91	    /// Local timestamp representing when this display snapshot was captured.
92	    pub captured_at: DateTime<Local>,
93	    /// Primary usage window (typically short duration).
94	    pub primary: Option<RateLimitWindowDisplay>,
95	    /// Secondary usage window (typically weekly).
96	    pub secondary: Option<RateLimitWindowDisplay>,
97	    /// Optional credits metadata when available.
98	    pub credits: Option<CreditsSnapshotDisplay>,
99	}
