84	    pub(crate) fn finish_rate_limit_refresh(
85	        &self,
86	        rate_limits: &[RateLimitSnapshotDisplay],
87	        now: DateTime<Local>,
88	    ) {
89	        let rate_limits = if rate_limits.len() <= 1 {
90	            compose_rate_limit_data(rate_limits.first(), now)
91	        } else {
92	            compose_rate_limit_data_many(rate_limits, now)
93	        };
94	        #[expect(clippy::expect_used)]
95	        let mut state = self
96	            .rate_limit_state
97	            .write()
98	            .expect("status history rate-limit state poisoned");
99	        state.rate_limits = rate_limits;
100	        state.refreshing_rate_limits = false;
101	    }
102	}
